/* Замена tilda-animation-sbs-1.0 для стенда motion.mjs (fixtures/motion/tilda.html), не код Tilda: у элемента с
   data-animate-sbs-event создаётся обёртка tn-atom__sbs-anim-wrapper; intoview — при входе в экран обёртка получает
   бесконечную CSS-анимацию (пульс); scroll — сдвиг X 340 px на 500 px прокрутки от «верх элемента у низа окна».
   На ширине < 1200 без data-animate-mobile="y" обёртки нет (как у Tilda). */
(function () {
  var narrow = window.innerWidth < 1200;
  [].slice.call(document.querySelectorAll('[data-animate-sbs-event]')).forEach(function (el) {
    if (narrow && el.getAttribute('data-animate-mobile') !== 'y') return;
    var atom = el.querySelector('.tn-atom'); var w = document.createElement('div');
    w.className = 'tn-atom__sbs-anim-wrapper'; atom.parentNode.insertBefore(w, atom); w.appendChild(atom);
    var ev = el.getAttribute('data-animate-sbs-event');
    if (ev === 'intoview') {
      var io = new IntersectionObserver(function (l) { l.forEach(function (e) { if (e.isIntersecting) { w.classList.add('t-sbs-anim_started', 'pulse'); io.disconnect(); } }); });
      io.observe(el);
    }
    if (ev === 'scroll') {
      var upd = function () { var r = el.getBoundingClientRect(); var p = Math.max(0, Math.min(1, (innerHeight - r.top) / 500)); w.style.transform = 'translateX(' + Math.round(340 * p) + 'px)'; };
      addEventListener('scroll', upd, { passive: true }); upd();
    }
  });
})();
